        routing_chat_help: '与用户面对面闲聊、问答、表情动作生成。调用最频繁，是人格塑造的核心任务，建议使用对话能力强、速度快的模型',
        routing_reasoning_help: '长文本理解（>100字）、工具调用（Function Calling）、复杂问题求解、结构化输出。自动从chat升级，需要强推理和JSON遵循能力',
        routing_diary_help: '每天定时（或手动触发）总结当天互动，生成第一人称日记。需要较好的叙事和归纳能力，对延迟不敏感',
        routing_memory_help: '每条对话写入时抽取关键词、重要性评分、语义标签、实体识别。后台高频调用（每轮1次），建议用便宜快速的模型即可',
        routing_consolidation_help: '夜间睡眠窗口整理记忆：短期记忆→中期摘要→长期事实→信念洞察→用户画像。离线批量任务，对延迟不敏感，需要深度归纳推理能力',
        routing_inner_monologue_help: '用户离开后自主生成内心想法（每小时约1次），写入记忆不主动打扰用户。风格自然口语化即可，建议便宜快速模型',
        routing_vision_describe_help: '用户发送图片时描述画面内容（OCR文字、场景、人物、情绪）。必须配置支持视觉输入的多模态模型（如Qwen-VL、GPT-4o、Gemini）',
        routing_activity_extraction_help: '每轮对话后后台分类当前活动类型（吃饭/工作/休息/娱乐等）。简单分类任务，极高频，建议用最便宜的快速模型',
        routing_emotion_analysis_help: '每轮对话后分析用户和角色的情绪效价/唤醒度。简单打分任务，极高频，建议用最便宜的快速模型',
        routing_knowledge_acquisition_help: '检测到知识缺口时后台搜索并学习新知识入库。低频后台任务，需要基本的信息总结能力',
        routing_interest_search_help: '内心独白触发时联网搜索感兴趣的话题（新闻、二次元、生活资讯等）。生成搜索query并总结结果，便宜模型即可',
        routing_translation_help: '跨语言 TTS 时将文本从显示语言翻译为 TTS 语言。仅在翻译服务选择 LLM 时使用此路由，简单翻译任务，便宜模型即可',
