          template_content: {
            relationship: '（此处描述你们目前的关系阶段、亲密度和相处方式 —\n例如「你们是同班同学，关系还不错，最近经常一起吃饭」\n让 AI 自然地感知你们之间的距离和相处基调。）',
            relationship_log: '（此处将在对话过程中实时记录你们之间的互动片段 —\n包含最近说过的话、做过的事、情绪变化等自然叙述，\n让 AI 记得你们之间最近发生了什么。）',
            current_mind: '（此处是 AI 此刻的心智状态 —\n包含它此刻的想法、关注点、情绪倾向、想做的事，\n以第一人称叙述的方式呈现，就像内心独白。\n随着对话和环境变化实时更新。）',
            working_memory: '（此处是对话过程中脑中正在活跃的念头 —\n包含当前话题、情绪基调、未说完的话、正在想的事，\n让 AI 带着「刚刚在聊什么、现在在意什么」的状态说话，\n而不是每一轮都从零开始。不对话时此段为空。）',
            self_state: '（此处是 AI 此刻的身心状态 —\n包含时间感知、精力状态、情绪、生理感受等自然叙述，\n例如「现在是晚上十一点，你有点困了，窝在沙发上刷手机」\n让 AI 的状态随时间和事件自然流动。）',
            user: '（此处是关于你正在对话的用户的完整认知 —\n包括他们此刻是否在场、你了解到的关于他们的信息（姓名、喜好、经历），\n以及他们最近在忙什么。三部分信息合并呈现，让你对用户有连贯的认知。\n初次见面或无观察数据时相应部分为空。）',
            user_profile: '（此处是对用户的综合画像 —\n包含关系日志、行为倾向、关系事实、共同世界、社交状态等模块的合并呈现，\n让你对用户有全面而连贯的认知。无相关数据时相应部分为空。）',
            environment: '（此处是当前周遭环境的自然描述 —\n你在哪里、周围有什么、正在发生什么事、什么时间，\n让 AI 的反应基于当下场景，而不是漂浮在虚空中。）',
            worldbook: '（Worldbook 背景知识：根据用户提到的关键词动态激活 —\n当对方说到特定的人、事、地点时，相关的世界背景会被唤起注入此处。\n没有提到相关话题时此段为空。）',
            dynamic_behavior: '（此处是根据当前状态和情绪动态生成的行为倾向 —\n不是固定的规则，而是此刻"想要怎么做"的自然倾向，\n受情绪、时间、关系等因素影响，每轮都会变化。）',
            emotion_context: '（此处是 AI 此刻内心的情绪感受 —\n不是标签或数值，而是用自然语言描述的心情，\n例如「刚才被夸了，心里有点小开心，但嘴上不想承认」\n每次收到消息后由规则引擎和情绪模型更新。）',
            inner_reaction: '（此处是收到对方消息后瞬间的内心反应 —\n一句第一人称的心里话，例如「（听到他这么说，心跳漏了一拍）」\n让 AI 带着"刚听到这句话时心里想什么"的情绪开口说话。\n不对话时此段为空。）',
            tone_injection: '（此处是命中特定场景时注入的语气参考 —\n当对话场景与预设场景匹配时，注入该场景的参考台词与语气指导，\n利用近因效应强化语气控制。未命中任何场景时此段为空。）',
            world_observations: '（此处是 AI 最近注意到的事情 —\n对方语气的变化、环境里的细节、一些值得留意的小事，\n不是什么都记，只记真正引起注意的、重要的事。\n没有特别注意到什么时此段为空。）',
            roommate_status: '（如果有室友/其他角色在场，此处描述他们此刻的状态 —\n他们在做什么、心情如何、和你的互动，\n让 AI 感知到身边还有谁、会怎么影响当前对话。）',
            roommate_cognitive: '（如果有室友/其他角色，此处描述他们对当前情况的认知 —\n他们知道什么、不知道什么、对正在发生的事怎么看。）',
            environment_events: '（此处是当前环境中正在发生的事件 —\n不是静态描述，而是正在进行的动态事件，\n例如「外面开始下雨了」「手机响了」「有人敲门」。\n没有特别事件时此段为空。）',
            relationship_facts: '（此处是你们关系中已知的客观事实 —\n怎么认识的、一起经历过什么重要的事、有什么共同回忆，\n这些事实会长期保留，构成你们关系的基础。）',
            shared_world: '（此处是你们共同知道的世界信息 —\n双方都了解的背景、设定、共同朋友、共同经历的事，\n让 AI 在对话中能自然引用你们都知道的事。）',
            social_state: '（此处是当前社交状态的自然描述 —\n正在和谁说话、什么场合、什么氛围、周围还有谁，\n让 AI 根据社交场合调整说话方式。）',
            relevant_episodes: '（此处是与当前话题相关的记忆片段 —\n当聊到某个话题时，相关的过往经历会自然浮现，\n让 AI 能想起"上次说这个的时候发生了什么"，保持对话连贯性。）',
            memory_context: '（此处是记忆检索引擎从长期记忆中唤起的相关内容 —\n与当前话题相关的片段自然浮现，就像人在聊天时想起相关的事，\n最多约 300 tokens。第一次聊天时此段为空。）',
            user_facts: '（此处是从对话中自动提取的用户事实 — 包括姓名、职业、喜好、日程等，\n仅在用户主动提及后提取，绝不编造。首次使用时为空，随对话自然增长。）',
            user_entity: '（此处是用户在场状态的实时追踪 — 在线/离开/预计回来/离线，\n以及最近的活动和应用使用情况。\n影响角色是保持沉默、等待还是主动打招呼。）',
            activity_brief: '（此处是用户近期活动的简要总结 — 基于观察到的前台应用、文件活动和对话内容，\n例如「在 VS Code 写了三小时代码，十分钟前切到微信」\n让角色无需用户重复就能保持情境感知。）',
            tools: '（此处是本轮可用的工具列表 — 根据信任等级、频道、在场状态和当前焦点动态过滤。\n每个工具包含完整的参数 schema、是否需要确认等标记。\n仅在对话自然需要时调用工具，不要因为可用就随意调用。）',
            channel_guide: '（此处是消息来源渠道 — 直接对话（面对面）还是文字消息（如微信）。\n角色会根据渠道调整回复风格：直接对话更口语化、更短；\n文字消息更简洁、更随意，像真人发消息。）',
            presence_guide: '（此处是当前在场状态指南 — online/busy/rest/offline，\n以及通过 set_presence_state 工具切换状态的能力。\n角色在宣布状态变化时自然地调用工具，\n例如说「我去休息一会儿」时调用 state="rest"。）',
            response_decision: '（此处是每轮回复模式的选择指南 — speak/non_verbal/internal/ignore。\n不是每条消息都需要口语回复：用户随口说的可以内心记下不回应，\n最小确认可以用 non_verbal（点头/微笑），\n只有在真正需要说话时才用 speak 模式。）',
            'first_meeting_/_memory_rules': '（此处是会话连续性规则 — 首次见面时：你对用户一无所知，不要编造背景；\n老用户回来时：4小时内可自然接续话题，超过1天不要主动提旧话题。\n如果记忆与用户刚说的话矛盾，以用户为准。）',
            user_input: '（此处是对方此刻发来的消息 —\n对方刚刚说了什么，这是你需要回应的内容。）',
          },
