        routing_translation: 'Translation',
        routing_chat_help: 'Face-to-face chat, Q&A, expression and gesture generation. Most frequently called task, core for persona building. Choose a model with strong dialogue ability and fast response',
        routing_reasoning_help: 'Long text comprehension (>100 chars), tool calls (Function Calling), complex problem solving, structured output. Auto-upgraded from chat; requires strong reasoning and JSON-following ability',
        routing_diary_help: 'Summarize daily interactions at scheduled time (or manual trigger), generate first-person diary entries. Needs good narrative and summarization ability; latency insensitive',
        routing_memory_help: 'Extract keywords, importance score, semantic tags, entity recognition on each conversation write. High-frequency background call (once per turn); cheap fast model is sufficient',
        routing_consolidation_help: 'Nightly memory organization during sleep window: short→mid-term summary→long-term facts→belief insights→user profile. Offline batch task; latency insensitive; needs deep inductive reasoning',
        routing_inner_monologue_help: 'Autonomous inner thought generation when user is away (~once per hour), written to memory without interrupting user. Natural colloquial style; cheap fast model recommended',
        routing_vision_describe_help: 'Describe image content when user sends photos (OCR text, scene, people, mood). MUST configure a vision-capable multimodal model (e.g. Qwen-VL, GPT-4o, Gemini)',
        routing_activity_extraction_help: 'Background activity type classification after each conversation (eating/working/resting/playing etc.). Simple classification, extremely high frequency; use the cheapest fastest model',
        routing_emotion_analysis_help: 'Background emotion valence/arousal analysis after each turn. Simple scoring task, extremely high frequency; use the cheapest fastest model',
        routing_knowledge_acquisition_help: 'Background search and knowledge acquisition when knowledge gaps are detected. Low-frequency background task; basic summarization ability needed',
        routing_interest_search_help: 'Web search for interesting topics during inner monologue (news, anime, lifestyle etc.). Generates search queries and summarizes results; cheap model is sufficient',
        routing_translation_help: 'Translates text from display language to TTS language for cross-language TTS. Only used when translation provider is set to LLM. Simple task, cheap model is sufficient',
        // Routing
        routing_description: 'Configure independent models per task. Choose appropriate models to balance experience and cost. Default uses SiliconFlow with free tier on registration.',
