        routing_chat_help: 'ユーザーとの雑談・Q&A・表情動作生成。最も呼び出し頻度が高く、人格形成のコアタスク。対話能力が高くレスポンスの速いモデル推奨',
        routing_reasoning_help: '長文理解（>100字）・ツール呼び出し（Function Calling）・複雑な問題解決・構造化出力。chatから自動昇格。強い推論力とJSON従順性が必要',
        routing_diary_help: '毎日定時（または手動）でその日の交流をまとめ、一人称日記を生成。高い物語力と要約力が必要だが、レイテンシは許容される',
        routing_memory_help: '会話書き込み時にキーワード・重要度スコア・意味タグ・エンティティを抽出。高頻度バックグラウンド（1ターン毎）。安価で高速なモデルで十分',
        routing_consolidation_help: '夜間睡眠ウィンドウで記憶を整理：短期→中期要約→長期事実→信念洞察→ユーザープロファイル。オフライン一括処理。深い帰納推論力が必要',
        routing_inner_monologue_help: 'ユーザー離席中に自律的に内的思考を生成（約1時間に1回）、記憶に書き込みユーザーを邪魔しない。自然な口語調であればよく、安価で高速なモデル推奨',
        routing_vision_describe_help: 'ユーザーが画像送信時に内容を記述（OCRテキスト・風景・人物・感情）。視覚入力対応のマルチモーダルモデル必須（例：Qwen-VL、GPT-4o、Gemini）',
        routing_activity_extraction_help: '各会話後に現在のアクティビティタイプを分類（食事/仕事/休息/娯楽など）。単純分類タスク、超高頻度。最も安価で高速なモデル推奨',
        routing_emotion_analysis_help: '各ターン後にユーザーとキャラの感情価・覚醒度を分析。単純スコアリングタスク、超高頻度。最も安価で高速なモデル推奨',
        routing_knowledge_acquisition_help: '知識ギャップ検出時にバックグラウンドで検索し新知識を学習。低頻度バックグラウンドタスク。基本的な要約力があれば十分',
        routing_interest_search_help: '内心独白トリガー時に興味のある話題（ニュース・アニメ・生活情報など）をWeb検索。検索クエリ生成と結果要約、安価なモデルで十分',
        routing_translation_help: 'クロス言語 TTS 時にテキストを表示言語から TTS 言語に翻訳。翻訳サービスで LLM 選択時のみ使用。単純な翻訳タスク、安価なモデルで十分',
        // Routing
