const savedLang =
  (typeof localStorage !== 'undefined' && localStorage.getItem('vivian-lang')) || 'zh-CN';

void i18n.use(initReactI18next).init({
  resources,
  lng: savedLang,
  fallbackLng: 'zh-CN',
  nsSeparator: false,
  keySeparator: '.',
  interpolation: {
    escapeValue: false,
  },
  returnNull: false,
});

export const changeLanguage = (lng: string) => {
  if (typeof localStorage !== 'undefined') {
    localStorage.setItem('vivian-lang', lng);
  }
  return i18n.changeLanguage(lng);
};

export default i18n;
